pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 n, uint64 t, uint256 f, bytes32 h, bytes32 b) internal {
        uint64 numBefore;
        try c.number() returns (uint64 __r) { numBefore = __r; } catch { return; }
        uint64 tsBefore;
        try c.timestamp() returns (uint64 __r) { tsBefore = __r; } catch { return; }
        uint256 bfBefore;
        try c.basefee() returns (uint256 __r) { bfBefore = __r; } catch { return; }
        bytes32 hBefore;
        try c.hash() returns (bytes32 __r) { hBefore = __r; } catch { return; }
        uint64 snBefore;
        try c.sequenceNumber() returns (uint64 __r) { snBefore = __r; } catch { return; }
        bytes32 bBefore;
        try c.batcherHash() returns (bytes32 __r) { bBefore = __r; } catch { return; }
        uint256 ohBefore;
        try c.l1FeeOverhead() returns (uint256 __r) { ohBefore = __r; } catch { return; }
        uint256 scBefore;
        try c.l1FeeScalar() returns (uint256 __r) { scBefore = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(n, t, f, h, n, b, f, f) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.number() == numBefore &&
            c.timestamp() == tsBefore &&
            c.basefee() == bfBefore &&
            c.hash() == hBefore &&
            c.sequenceNumber() == snBefore &&
            c.batcherHash() == bBefore &&
            c.l1FeeOverhead() == ohBefore &&
            c.l1FeeScalar() == scBefore);
    }

    function testFuzz_run(uint64 n, uint64 t, uint256 f, bytes32 h, bytes32 b) public {
        _run(n, t, f, h, b);
    }

    receive() external payable {}
}
